    /// 点是否落在中国大陆多边形内（港澳台与境外返回 false）。
    public static func isMainland(lat: Double, lon: Double) -> Bool {
        if lon < bbox.minLon || lon > bbox.maxLon || lat < bbox.minLat || lat > bbox.maxLat { return false }
        var inside = false
        for ring in rings {
            guard ring.count >= 3 else { continue }
            var j = ring.count - 1
            for i in 0..<ring.count {
                let xi = ring[i].0, yi = ring[i].1
                let xj = ring[j].0, yj = ring[j].1
                if ((yi > lat) != (yj > lat)) && (lon < (xj - xi) * (lat - yi) / (yj - yi) + xi) {
                    inside.toggle()
                }
                j = i
            }
        }
        return inside
    }

    /// WGS-84 → GCJ-02（标准偏转算法）。
    public static func wgs84ToGcj02(lat: Double, lon: Double) -> (lat: Double, lon: Double) {
        var dLat = transformLat(lon - 105.0, lat - 35.0)
        var dLon = transformLon(lon - 105.0, lat - 35.0)
        let radLat = lat / 180.0 * Double.pi
        let magic = 1 - ee * sin(radLat) * sin(radLat)
        let sqrtMagic = sqrt(magic)
        dLat = (dLat * 180.0) / ((a * (1 - ee)) / (magic * sqrtMagic) * Double.pi)
        dLon = (dLon * 180.0) / (a / sqrtMagic * cos(radLat) * Double.pi)
        return (lat + dLat, lon + dLon)
    }

    /// GCJ-02 → WGS-84（迭代反解，误差 < 0.5 m）。
    public static func gcj02ToWgs84(lat: Double, lon: Double) -> (lat: Double, lon: Double) {
        var wgsLat = lat
        var wgsLon = lon
        for _ in 0..<4 {
            let gcj = wgs84ToGcj02(lat: wgsLat, lon: wgsLon)
            wgsLat -= gcj.lat - lat
            wgsLon -= gcj.lon - lon
        }
        return (wgsLat, wgsLon)
    }

    /// 设备/后端使用的 WGS-84 → 地图绘制使用的坐标（大陆内为 GCJ-02）。
    public static func display(lat: Double, lon: Double) -> (lat: Double, lon: Double) {
        isMainland(lat: lat, lon: lon) ? wgs84ToGcj02(lat: lat, lon: lon) : (lat, lon)
    }

    /// 地图点击/拖动返回的坐标 → 设备/后端使用的 WGS-84。
    public static func wgs(lat: Double, lon: Double) -> (lat: Double, lon: Double) {
        isMainland(lat: lat, lon: lon) ? gcj02ToWgs84(lat: lat, lon: lon) : (lat, lon)
    }

    private static func transformLat(_ x: Double, _ y: Double) -> Double {
        var r = -100.0 + 2.0 * x + 3.0 * y + 0.2 * y * y + 0.1 * x * y + 0.2 * sqrt(abs(x))
        r += (20.0 * sin(6.0 * x * Double.pi) + 20.0 * sin(2.0 * x * Double.pi)) * 2.0 / 3.0
        r += (20.0 * sin(y * Double.pi) + 40.0 * sin(y / 3.0 * Double.pi)) * 2.0 / 3.0
        r += (160.0 * sin(y / 12.0 * Double.pi) + 320.0 * sin(y * Double.pi / 30.0)) * 2.0 / 3.0
        return r
    }

    private static func transformLon(_ x: Double, _ y: Double) -> Double {
        var r = 300.0 + x + 2.0 * y + 0.1 * x * x + 0.1 * x * y + 0.1 * sqrt(abs(x))
        r += (20.0 * sin(6.0 * x * Double.pi) + 20.0 * sin(2.0 * x * Double.pi)) * 2.0 / 3.0
        r += (20.0 * sin(x * Double.pi) + 40.0 * sin(x / 3.0 * Double.pi)) * 2.0 / 3.0
        r += (150.0 * sin(x / 12.0 * Double.pi) + 300.0 * sin(x / 30.0 * Double.pi)) * 2.0 / 3.0
        return r
    }
